<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{Article,Page}; use App\Services\{AdminAudit,ContentSanitizer}; use Illuminate\Http\Request; use Illuminate\Support\Str;
class ContentController extends Controller {
 public function index(string $type){$model=$this->model($type);return view('admin.content.index',['type'=>$type,'items'=>$model::orderByDesc('published_at')->latest()->paginate(25)]);} public function create(string $type){$model=$this->model($type);return view('admin.content.form',['type'=>$type,'item'=>new $model(['status'=>'draft','published_at'=>now()])]);} public function edit(string $type,int $id){$model=$this->model($type);return view('admin.content.form',['type'=>$type,'item'=>$model::findOrFail($id)]);}
 public function store(Request $r,string $type,ContentSanitizer $sanitizer,AdminAudit $audit){$model=$this->model($type);$item=$model::create($this->data($r,$sanitizer));$audit->record($type.'.created',$item);return redirect()->route('admin.content.edit',[$type,$item])->with('status','Contenu créé.');} public function update(Request $r,string $type,int $id,ContentSanitizer $sanitizer,AdminAudit $audit){$model=$this->model($type);$item=$model::findOrFail($id);$item->update($this->data($r,$sanitizer,$item));$audit->record($type.'.updated',$item,$item->getChanges());return back()->with('status','Contenu enregistré.');}
 private function model(string $type):string{abort_unless(in_array($type,['articles','pages'],true),404);return $type==='articles'?Article::class:Page::class;} private function data(Request $r,ContentSanitizer $s,object $item=null):array{$model=$this->model($r->route('type'));$d=$r->validate(['title'=>'required|string|max:255','slug'=>'nullable|alpha_dash|max:255|unique:'.(new $model)->getTable().',slug'.($item?', '.$item->id:''),'content_html'=>'nullable|string|max:100000','excerpt'=>'nullable|string|max:1000','status'=>'required|in:draft,published','published_at'=>'nullable|date','seo_title'=>'nullable|string|max:255','seo_description'=>'nullable|string|max:500','seo_robots'=>'nullable|string|max:100']);$d['slug']=($d['slug']??null)?:Str::slug($d['title']);$d['content_html']=$s->sanitize($d['content_html']??'')['html'];if($d['status']==='published'&&!($d['published_at']??null))$d['published_at']=$item?->published_at??now();if(!$item){$d+=['legacy_wp_id'=>random_int(1_000_000_000,2_000_000_000),'original_title'=>$d['title'],'legacy_url'=>'/'.$d['slug'],'source_type'=>'manual'];}return $d;}
}
